import { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { Calendar, MapPin, Users, Edit, Trash2, ArrowLeft } from 'lucide-react';
import api from '../services/api';
import './EventDetails.css';

export default function EventDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [event, setEvent] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchEvent();
  }, [id]);

  const fetchEvent = async () => {
    try {
      const { data } = await api.get('/events');
      const found = data.find(e => e._id === id);
      if (found) setEvent(found);
      setLoading(false);
    } catch (err) {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this event?')) {
      try {
        await api.delete(`/events/${id}`);
        navigate('/');
      } catch (err) {
        alert('Failed to delete event');
      }
    }
  };



  if (loading) return <div className="page-center"><div className="loader"></div></div>;
  if (!event) return <div className="page-center"><h2>Event Not Found</h2><Link to="/" className="btn btn-primary mt-2">Go Back</Link></div>;

  const imageUrl = event.image ? `http://localhost:5000/uploads/${event.image}` : 'data:image/svg+xml;charset=UTF-8,%3Csvg%20width%3D%221200%22%20height%3D%22400%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%231e293b%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20font-family%3D%22sans-serif%22%20font-size%3D%2220%22%20fill%3D%22%2394a3b8%22%20text-anchor%3D%22middle%22%20dy%3D%22.3em%22%3ENo%20Image%3C%2Ftext%3E%3C%2Fsvg%3E';
  const date = new Date(event.date).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  const deadline = new Date(event.registrationDeadline).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

  const isFull = event.registeredCount >= event.capacity;
  const isInactive = event.status !== 'Upcoming';

  return (
    <div className="event-details container animate-fade-in">
      <Link to="/" className="back-link"><ArrowLeft size={18} /> Back to Events</Link>
      
      <div className="details-header glass-panel">
        <img src={imageUrl} alt={event.title} className="details-image" />
        <div className="details-content">
          <div className="details-meta" style={{display: 'flex', gap: '0.5rem', marginBottom: '1rem'}}>
            <span className="badge">{event.category}</span>
            {event.isFeatured && <span className="badge badge-featured">🌟 Featured</span>}
            {event.isDraft && <span className="badge badge-draft">DRAFT</span>}
          </div>
          <div className="status-indicator">
            <span className={`status-dot status-${event.status?.toLowerCase() || 'upcoming'}`}></span>
            {event.status || 'Upcoming'}
          </div>
          <h1 className="details-title" style={{marginTop: '0.5rem'}}>{event.title}</h1>
          
          <div className="details-info-grid">
            <div className="info-item">
              <Calendar className="icon-accent" />
              <div>
                <p className="info-label">Date</p>
                <p className="info-value">{date}</p>
              </div>
            </div>
            <div className="info-item">
              <MapPin className="icon-accent" />
              <div>
                <p className="info-label">Location</p>
                <p className="info-value">{event.location}</p>
              </div>
            </div>
            <div className="info-item">
              <Users className="icon-accent" />
              <div>
                <p className="info-label">Capacity</p>
                <p className="info-value">{event.registeredCount || 0} / {event.capacity}</p>
              </div>
            </div>
          </div>
          
          <div className="details-actions">
            <div className="action-group">
              <Link to={`/edit/${event._id}`} className="btn btn-outline"><Edit size={18} /> Edit</Link>
              <button onClick={handleDelete} className="btn btn-danger"><Trash2 size={18} /> Delete</button>
            </div>
          </div>
        </div>
      </div>
      
      <div className="details-body glass-panel">
        <h2>About this Event</h2>
        <p className="details-description">{event.description}</p>
        <div className="deadline-notice">
          <strong>Registration Deadline:</strong> {deadline}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { ArrowLeft, Save } from 'lucide-react';
import api from '../services/api';
import './EventForm.css';

export default function EventForm() {
  const { id } = useParams();
  const isEditing = !!id;
  const navigate = useNavigate();
  
  const [formData, setFormData] = useState({
    title: '',
    category: '',
    location: '',
    date: '',
    registrationDeadline: '',
    capacity: 0,
    description: '',
    status: 'Upcoming',
    isDraft: true,
    isFeatured: false
  });
  
  const [imageFile, setImageFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [dateError, setDateError] = useState('');

  useEffect(() => {
    if (isEditing) {
      fetchEventData();
    }
  }, [id]);

  const fetchEventData = async () => {
    try {
      const { data } = await api.get('/events');
      const found = data.find(e => e._id === id);
      if (found) {
        setFormData({
          title: found.title || '',
          category: found.category || '',
          location: found.location || '',
          date: found.date ? found.date.split('T')[0] : '',
          registrationDeadline: found.registrationDeadline ? found.registrationDeadline.split('T')[0] : '',
          capacity: found.capacity || 0,
          description: found.description || '',
          status: found.status || 'Upcoming',
          isDraft: found.isDraft ?? true,
          isFeatured: found.isFeatured ?? false
        });
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const handleFileChange = (e) => {
    setImageFile(e.target.files[0]);
  };

  useEffect(() => {
    if (!formData.date || !formData.registrationDeadline) {
      setDateError('');
      return;
    }

    const eventDate = new Date(formData.date);
    const deadline = new Date(formData.registrationDeadline);

    if (deadline > eventDate) {
      setDateError('Registration deadline cannot be later than event date.');
      return;
    }

    setDateError('');
  }, [formData.date, formData.registrationDeadline]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (dateError) {
      alert(dateError);
      return;
    }

    setLoading(true);

    try {
      if (isEditing) {
        await api.put(`/events/${id}`, formData);
      } else {
        const formPayload = new FormData();
        Object.keys(formData).forEach(key => {
          formPayload.append(key, formData[key]);
        });
        if (imageFile) {
          formPayload.append('image', imageFile);
        }
        await api.post('/events', formPayload, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
      }
      navigate('/');
    } catch (err) {
      alert(err.response?.data?.message || err.message || 'Failed to save event');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="event-form-page container animate-fade-in">
      <Link to="/" className="back-link"><ArrowLeft size={18} /> Back</Link>
      
      <div className="form-container glass-panel">
        <div className="form-header">
          <h2>{isEditing ? 'Edit Event' : 'Create New Event'}</h2>
          <p className="text-muted">Fill out the details below to {isEditing ? 'update' : 'publish'} the event.</p>
        </div>

        <form onSubmit={handleSubmit} className="event-form">
          <div className="form-grid">
            <div className="input-group">
              <label className="input-label">Title *</label>
              <input type="text" name="title" value={formData.title} onChange={handleChange} className="input-field" required />
            </div>

            <div className="input-group">
              <label className="input-label">Category *</label>
              <select name="category" value={formData.category} onChange={handleChange} className="input-field" required>
                <option value="">Select Category</option>
                <option value="Conference">Conference</option>
                <option value="Workshop">Workshop</option>
                <option value="Seminar">Seminar</option>
                <option value="Social">Social</option>
                <option value="Other">Other</option>
              </select>
            </div>

            <div className="input-group">
              <label className="input-label">Location *</label>
              <input type="text" name="location" value={formData.location} onChange={handleChange} className="input-field" required />
            </div>

            <div className="input-group">
              <label className="input-label">Capacity *</label>
              <input type="number" name="capacity" value={formData.capacity} onChange={handleChange} className="input-field" min="1" required />
            </div>

            <div className="input-group">
              <label className="input-label">Event Date *</label>
              <input
                type="date"
                name="date"
                value={formData.date}
                onChange={handleChange}
                className="input-field"
                min={formData.registrationDeadline || undefined}
                required
              />
            </div>

            <div className="input-group">
              <label className="input-label">Registration Deadline *</label>
              <input
                type="date"
                name="registrationDeadline"
                value={formData.registrationDeadline}
                onChange={handleChange}
                className="input-field"
                max={formData.date || undefined}
                required
              />
            </div>

            {isEditing && (
              <div className="input-group">
                <label className="input-label">Status</label>
                <select name="status" value={formData.status} onChange={handleChange} className="input-field">
                  <option value="Upcoming">Upcoming</option>
                  <option value="Completed">Completed</option>
                  <option value="Cancelled">Cancelled</option>
                </select>
              </div>
            )}

            {!isEditing && (
              <div className="input-group">
                <label className="input-label">Event Image</label>
                <input type="file" name="image" onChange={handleFileChange} className="input-field file-input" accept="image/*" />
              </div>
            )}
          </div>

          <div className="input-group">
            <label className="input-label">Description *</label>
            <textarea name="description" value={formData.description} onChange={handleChange} className="input-field text-area" rows="4" required></textarea>
          </div>

          {dateError && <p className="form-error-message">{dateError}</p>}

          <div className="checkbox-group-container">
            <label className="checkbox-label">
              <input type="checkbox" name="isDraft" checked={formData.isDraft} onChange={handleChange} />
              <span>Save as Draft (Hidden from public)</span>
            </label>
            <label className="checkbox-label">
              <input type="checkbox" name="isFeatured" checked={formData.isFeatured} onChange={handleChange} />
              <span>Feature this event</span>
            </label>
          </div>

          <div className="form-actions">
            <button type="button" onClick={() => navigate(-1)} className="btn btn-outline">Cancel</button>
            <button type="submit" className="btn btn-primary" disabled={loading || !!dateError}>
              <Save size={18} />
              {loading ? 'Saving...' : 'Save Event'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
